// Structured-output validation: never trust raw LLM JSON.
// Fails safe: any unparseable/enum-invalid output becomes a review fallback.
const ven = $('Validate & Normalize').first().json;
const i = $json;
const duration_ms = Math.max(0, Date.now() - Date.parse(ven.received_at)) || 0;

const ALLOWED = {
  sentiment: ['positive', 'neutral', 'negative', 'mixed', 'unknown'],
  category: ['product_quality', 'shipping', 'billing', 'technical_issue', 'customer_support', 'general', 'unknown'],
  urgency: ['low', 'medium', 'high', 'unknown'],
};

let llm_error = null;
let result = null;

try {
  const cand = i && i.candidates && i.candidates[0];
  const parts = (cand && cand.content && cand.content.parts) || [];
  const text = parts.map((p) => p.text || '').join('');
  if (!cand || !text) throw new Error('empty_response');
  const parsed = JSON.parse(text);
  result = {};
  for (const field of ['sentiment', 'category', 'urgency']) {
    let v = parsed ? parsed[field] : undefined;
    if (typeof v !== 'string') { v = 'unknown'; llm_error = llm_error || 'invalid_llm_field_' + field; }
    v = v.trim().toLowerCase();
    if (!ALLOWED[field].includes(v)) { v = 'unknown'; llm_error = llm_error || 'enum_violation_' + field; }
    result[field] = v;
  }
  result.summary = typeof (parsed || {}).summary === 'string' ? parsed.summary.slice(0, 200) : 'No summary provided by model.';
} catch (e) {
  llm_error = llm_error || 'unparseable_llm_json';
  result = {
    sentiment: 'unknown',
    category: 'unknown',
    urgency: 'unknown',
    summary: 'AI output could not be validated; queued for human review.',
  };
}

return [{ json: {
  request_id: ven.request_id,
  source: ven.source,
  unit: ven.unit,
  received_at: ven.received_at,
  duration_ms,
  result,
  llm_error,
}}];

// Deterministic routing: pure rules, no LLM in the decision path.
// This node also performs the mini-RAG retrieval that grounds suggested
// responses for the normal route. It never calls any external service.
const i = $json;
const r = i.result || {};
const reasons = [];

let route;
if (i.llm_error) {
  route = 'review';
  reasons.push('llm_error -> safe review fallback (output not trusted)');
}
if (r.urgency === 'high' && !i.llm_error) {
  route = 'high_priority';
  reasons.push('urgency=high -> high-priority review queue');
}
if (!i.llm_error && route !== 'high_priority' && (r.category === 'unknown' || r.sentiment === 'unknown' || r.urgency === 'unknown')) {
  route = 'review';
  reasons.push('unknown classification field -> human review instead of a guess');
}
if (!route) {
  route = 'normal';
  reasons.push('all fields validated -> routine processing');
}

// Mini-RAG grounding (deterministic keyword retrieval over the embedded KB).
const KB = [{"id": "kb-shipping-delays", "title": "Shipping delays and tracking", "keywords": ["shipping", "shipment", "delivery", "delivered", "arrived", "tracking", "late", "delayed", "package", "courier", "po box"], "guidance": "Per our shipping policy, domestic orders usually arrive in 3-5 business days and international orders in 7-14 days. Once an order leaves the warehouse, live tracking appears on the order page."}, {"id": "kb-damaged-item", "title": "Damaged or defective items", "keywords": ["damaged", "broken", "defective", "cracked", "dented", "leaking", "missing parts", "arrived broken"], "guidance": "Damaged-in-transit items are handled by the support team: report the item and keep the packaging, and the standard process is to inspect the report and prepare a replacement or remedy per the returns policy."}, {"id": "kb-billing-charges", "title": "Billing and duplicate charges", "keywords": ["charged", "charge", "charged twice", "billing", "invoice", "receipt", "payment", "duplicate payment", "money taken", "refund"], "guidance": "Duplicate charges are reviewed by the billing team. Statements and receipts are available from the billing page, and every payment record has a transaction ID that the team can trace."}, {"id": "kb-app-issues", "title": "App crashes and technical issues", "keywords": ["crash", "crashes", "crashing", "bug", "error", "not loading", "broken app", "slow", "freeze", "frozen", "updates", "upload", "failed"], "guidance": "Known technical issues are tracked by the engineering team. A fresh app install usually resolves client-side problems, and crash reports attached to support tickets shorten diagnosis."}, {"id": "kb-support-response", "title": "Support availability and response times", "keywords": ["wait", "waiting", "no reply", "no response", "slow response", "response time", "support hours", "replied", "backlog", "ticket"], "guidance": "Standard support response time is within one business day, and urgent channels run during business hours. Ticket volume spikes can temporarily increase wait times."}, {"id": "kb-account-access", "title": "Account and sign-in access", "keywords": ["login", "log in", "sign in", "password", "password reset", "locked out", "account locked", "account access", "verification"], "guidance": "Password resets and account recovery are self-service from the sign-in page. Account locks clear automatically after the cool-down window passes."}, {"id": "kb-data-privacy", "title": "Data privacy and deletion requests", "keywords": ["privacy", "personal data", "delete my data", "gdpr", "data deletion", "unsubscribe", "marketing mail", "opt out", " erase"], "guidance": "Data-deletion and opt-out requests are routed to the privacy team, which verifies ownership before erasing personal data in line with the published retention schedule."}, {"id": "kb-praise", "title": "Compliments and positive feedback", "keywords": ["thank you", "thanks", "excellent", "great", "love it", "amazing", "works great", "improved", "happy with", "praise", "best"], "guidance": "Positive feedback is shared weekly with the product and support teams, and recurring praise themes are tracked as signals for what to keep doing."}, {"id": "kb-feature-requests", "title": "Feature requests and suggestions", "keywords": ["feature", "suggest", "suggestion", "would be nice", "wish it", "please add", "improvement idea", "roadmap"], "guidance": "Feature suggestions are logged for the product team and tagged by theme; popular recurring themes are surfaced on the public roadmap review."}, {"id": "kb-holding-units", "title": "Central intake and unit resolution (holding-company pattern)", "keywords": ["holding", "subsidiary", "unit", "branch", "store", "location", "franchise", "division"], "guidance": "Feedback entered without a specific unit stays in the central queue; naming a unit routes visibility to that unit while the group-level audit trail stays unified."}];
let kbSource = null;
let grounded = false;
let suggested_response = null;
if (route === 'normal') {
  const hay = String(i.feedback || '').toLowerCase();
  const tokenSet = new Set(hay.match(/[a-z0-9]+/g) || []);
  let best = null;
  let bestScore = 0;
  for (const entry of KB) {
    let score = 0;
    for (const kw of entry.keywords) {
      if (kw.includes(' ')) { if (hay.includes(kw)) score += 3; }
      else if (tokenSet.has(kw)) score += 2;
    }
    if (score > bestScore) { bestScore = score; best = entry; }
  }
  if (best && bestScore >= 3) {
    grounded = true;
    kbSource = best.id;
    suggested_response =
      'Thank you for your feedback. Reference: ' + best.title + ' — ' + best.guidance +
      ' (ref ' + i.request_id + ')';
  } else {
    suggested_response =
      'Thank you for your feedback. Our team has logged it (ref ' + i.request_id + ') and will follow up if needed.';
  }
}

return [{ json: {
  ...i,
  routing_decision: route,
  routing_reasons: reasons,
  review_required: route !== 'normal',
  suggested_response,
  response_grounded: route === 'normal' ? grounded : null,
  kb_source: grounded ? kbSource : null,
}}];

// Build the structured success response for the caller.
const i = $json;
return [{ json: {
  ...i,
  final_response: {
    success: true,
    request_id: i.request_id,
    unit: i.unit,
    result: i.result,
    routing_decision: i.routing_decision,
    routing_reasons: i.routing_reasons,
    review_required: i.review_required,
    suggested_response: i.suggested_response,
    response_grounded: i.response_grounded,
    kb_source: i.kb_source,
    llm: { provider: 'gemini', model: 'gemini-3.5-flash', llm_error: i.llm_error },
    processing_duration_ms: i.duration_ms,
    error: null,
  },
}}];

// Optional escalation hand-off. Disabled unless ESCALATION_WEBHOOK_URL is set.
// Runs on a side branch so the caller's response never depends on it.
let url = '';
try {
  url = (typeof $env !== 'undefined' && $env.ESCALATION_WEBHOOK_URL)
    ? String($env.ESCALATION_WEBHOOK_URL).trim()
    : '';
} catch (e) {
  url = '';
}
const i = $json;
return [{ json: {
  ...i,
  escalation_enabled: url !== '' && i.routing_decision !== 'normal',
  escalation_url: url,
}}];

// Optional persistent audit hand-off. Disabled unless AUDIT_WEBHOOK_URL is set.
// Side branch only: persistence failures never change the triage response.
let url = '';
let hmacSecret = '';
try {
  url = (typeof $env !== 'undefined' && $env.AUDIT_WEBHOOK_URL)
    ? String($env.AUDIT_WEBHOOK_URL).trim()
    : '';
  hmacSecret = (typeof $env !== 'undefined' && $env.AUDIT_HMAC_SECRET)
    ? String($env.AUDIT_HMAC_SECRET).trim()
    : '';
} catch (e) {
  url = '';
  hmacSecret = '';
}
const i = $json;
const raw = i.audit_row ? JSON.stringify(i.audit_row) : '';
const timestamp = String(Date.now());
let signature = '';
if (hmacSecret && raw) {
  const nodeCrypto = require('crypto');
  signature = nodeCrypto
    .createHmac('sha256', hmacSecret)
    .update(timestamp + '.' + raw)
    .digest('hex');
}
return [{ json: {
  ...i,
  audit_persist_enabled: url !== '' && !!raw,
  audit_persist_url: url,
  audit_persist_body: raw,
  audit_hmac_timestamp: signature ? timestamp : '',
  audit_hmac_signature: signature,
}}];

// Deterministic rejection: happens BEFORE the AI is ever called.
const i = $json;
const dur = Math.max(0, Date.now() - Date.parse(i.received_at)) || 0;
return [{ json: {
  ...i,
  final_response: {
    success: false,
    request_id: i.request_id,
    error: {
      code: i.problems[0] || 'invalid_request',
      message: 'Request failed validation. Nothing was classified and no AI credits were spent.',
      problems: i.problems,
    },
    processing_duration_ms: dur,
  },
}}];

// Build the audit row once, log it locally, and let the adjacent side branch
// persist it to the review queue when AUDIT_WEBHOOK_URL is configured.
// Keep this shape stable: the store and dashboard depend on it.
const i = $json;
let row;
if (!i.final_response) {
  row = { request_id: i.request_id, status: 'unknown_state', created_at: new Date().toISOString() };
} else if (i.final_response.success === false) {
  row = {
    request_id: i.final_response.request_id,
    created_at: new Date().toISOString(),
    source: i.source || null,
    unit: i.unit || null,
    status: 'rejected_pre_llm',
    routing_reasons: ['rejected before the LLM ran: ' + (i.problems || []).join(', ')],
    error_code: i.final_response.error.code,
  };
} else {
  const f = i.final_response;
  row = {
    request_id: f.request_id,
    created_at: new Date().toISOString(),
    source: i.source || null,
    unit: i.unit || null,
    sentiment: (f.result || {}).sentiment,
    category: (f.result || {}).category,
    urgency: (f.result || {}).urgency,
    summary: (f.result || {}).summary,
    routing_decision: f.routing_decision,
    routing_reasons: f.routing_reasons || [],
    review_status: f.review_required ? 'needs_review' : 'auto',
    suggested_response: f.suggested_response,
    response_grounded: f.response_grounded,
    kb_source: f.kb_source,
    llm_error: (f.llm || {}).llm_error,
    processing_duration_ms: f.processing_duration_ms,
  };
}
console.log('[AUDIT] ' + JSON.stringify(row));
return [{ json: { ...i, audit_row: row } }];
